    for item in nested_list:
        if isinstance(item, list):
            result.extend(flatten_list(item))
        else:
            result.append(item)
    return result
```

def trim_tuple(tuples, k):
    return [tuple(x[:k] for x in t) for t in tuples]
```

def convert_list_dictionary(list1, list2, list3):
    nested_dict = {}
    for i in range(len(list1)):
        nested_dict[list1[i]] = {}
        nested_dict[list1[i]][list2[i]] = list3[i]
    return nested_dict
```

def combinations_list(lst):
    result = [[]]
    for item in lst:
        result += [curr + [item] for curr in result]
    return result
```
